    AND t.subject_id = #{subjectId}
    AND t.type_code like concat('%', #{typeCode,jdbcType=VARCHAR}, '%')
    AND t.type_name like concat('%', #{typeName,jdbcType=VARCHAR}, '%')
    AND t.status = #{status}

order by t.sort asc, t.type_id asc


where t.subject_id = #{subjectId} and t.type_code = #{typeCode}
and t.type_id <> #{typeId}
limit 1

select count(1)
from spas_paper_question q
join spas_paper p on p.paper_id = q.paper_id
where p.subject_id = #{subjectId}
  and q.question_type = #{typeCode}

